const raw = $input.first().json.output || $input.first().json.text || $input.first().json.content || '';
let parsed;
try {
  const cleaned = raw.replace(/```json?\n?/gi, '').replace(/```/g, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch (e) {
  parsed = { risk_level: 'UNKNOWN', default_probability: null, key_signals: ['Parse error: ' + String(e.message)], recommendation: 'Manual review required.' };
}
return [{ json: parsed }];
